import subprocess, tempfile
from pathlib import Path
CASES=['( not ( True or False ) ) and ( False or True and True )\n', '( not ( True or False ) ) and ( False or False )\n', '( not ( True and False ) ) or ( True and True )\n', '( not ( True or True ) ) and ( True and True )\n', '( not ( False and False ) ) and ( True or True )\n', '( not ( True and True ) ) or ( True and False )\n', '( not ( True or True ) ) and ( False or True )\n', '( not ( True or False ) ) or ( True and False )\n', '( not ( False and True ) ) or ( False or False )\n', '( not ( False or True ) ) or ( False and False )\n', '( not ( False or True ) ) and ( False or True )\n', '( not ( True or True ) ) and ( True or False )\n', '( not ( True or False ) ) and ( False and False )\n', '( not ( True or True ) ) or ( False and True )\n', '( not ( True and False ) ) or ( False or False )\n', '( not ( True or False ) ) or ( True and True )\n', '( not ( False or False ) ) or ( True or False )\n', '( not ( False and False ) ) and ( True or False )\n', '( not ( True and False ) ) and ( True or True )\n', '( not ( False and True ) ) and ( False and True )\n']
SOURCE='class BinaryTree:\n    def __init__(self, root, left=None, right=None):\n        self.root = root\n        self.leftChild = left\n        self.rightChild = right\n\ndef postorder(string):  # 中缀改后缀 (Shunting Yard)\n    opStack, postList = [], []\n    inList = string.split()\n    prec = {\'(\': 0, \'or\': 1, \'and\': 2, \'not\': 3}\n    # 定义结合性：L 为左结合，R 为右结合\n    assoc = {\'or\': \'L\', \'and\': \'L\', \'not\': \'R\'}\n\n    for word in inList:\n        if word == \'(\':\n            opStack.append(word)\n        elif word == \')\':\n            while opStack and opStack[-1] != \'(\':\n                postList.append(opStack.pop())\n            opStack.pop()\n        elif word in (\'True\', \'False\'):\n            postList.append(word)\n        else:  # operator\n            # while opStack and prec[word] <= prec[opStack[-1]]:\n            # while opStack and (word != "not" and prec[word] <= prec[opStack[-1]]):\n            while (opStack and opStack[-1] in prec and (\n                    (assoc[word] == \'L\' and prec[word] <= prec[opStack[-1]]) or\n                    (assoc[word] == \'R\' and prec[word] < prec[opStack[-1]]))):\n                postList.append(opStack.pop())\n            opStack.append(word)\n    while opStack:\n        postList.append(opStack.pop())\n    return postList\n\ndef buildParseTree(infix):\n    postList = postorder(infix)\n    stack = []\n    for word in postList:\n        if word == \'not\':\n            child = stack.pop()\n            stack.append(BinaryTree(\'not\', child))\n        elif word in (\'True\', \'False\'):\n            stack.append(BinaryTree(word))\n        else:\n            right, left = stack.pop(), stack.pop()\n            stack.append(BinaryTree(word, left, right))\n    return stack[-1]\n\n# 定义运算符优先级\npriority = {\'or\': 1, \'and\': 2, \'not\': 3, \'True\': 4, \'False\': 4}\n\ndef printTree(tree):\n    """返回 token 列表"""\n    root = tree.root\n    if root in (\'True\', \'False\'):\n        return [root]\n\n    if root == \'not\':\n        child = tree.leftChild\n        # 若子优先级更低则加括号\n        child_tokens = printTree(child)\n        if priority[child.root] < priority[root]:\n            child_tokens = [\'(\'] + child_tokens + [\')\']\n        return [\'not\'] + child_tokens\n\n    # 二元操作符 and/or\n    left, right = tree.leftChild, tree.rightChild\n    left_tokens = printTree(left)\n    right_tokens = printTree(right)\n    if priority[left.root] < priority[root]:\n        left_tokens = [\'(\'] + left_tokens + [\')\']\n    if priority[right.root] < priority[root]:\n        right_tokens = [\'(\'] + right_tokens + [\')\']\n    return left_tokens + [root] + right_tokens\n\ndef main():\n    infix = input().strip()\n    Tree = buildParseTree(infix)\n    print(\' \'.join(printTree(Tree)))\n\nif __name__ == "__main__":\n    main()\n\n'
with tempfile.NamedTemporaryFile('w',suffix='.py') as f:
 f.write(SOURCE); f.flush()
 root=Path(__file__).parent/'data'
 for i,c in enumerate(CASES):
  o=subprocess.run(['python3',f.name],input=c,text=True,capture_output=True,check=True).stdout
  (root/f'{i}.in').write_text(c); (root/f'{i}.out').write_text(o)
